function hasDoublePair(nums: number[]): boolean {
  const s = [...nums].sort((a, b) => a - b);
  for (let i = 0; i < s.length; i++) {
    const target = 2 * s[i];
    let lo = 0, hi = s.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (s[mid] === target && mid !== i) return true;
      if (s[mid] === target) {
        // mid === i only happens for 0; a second 0 must sit right next to it
        if ((i > 0 && s[i - 1] === 0) || (i + 1 < s.length && s[i + 1] === 0)) return true;
        break; // a lone 0 has no partner; move on to the next value
      }
      if (s[mid] < target) lo = mid + 1; else hi = mid - 1;
    }
  }
  return false;
}

